   "tagline": "火燒蝦與半熟鴨蛋交織，海安路上四代人的甜蝦記憶",
   "story": "集品蝦仁飯已傳承四代，堅持使用產季限定的台灣火燒蝦，以柴魚與蝦頭熬煮的湯汁拌炒白飯，讓每一粒米都吸飽鮮甜滋味。店家與相隔不遠的矮仔成蝦仁飯，被視為海安路蝦仁飯的兩大門派，各有死忠支持者，也讓這條老街的蝦仁飯文化更加豐富。",
   "review": [
    "海安路上，集品的攤前總是聚著等待外帶或內用的人潮，湯飯拌炒的香氣混著蝦頭熬煮的鮮甜味飄散在空氣中，是府城人再熟悉不過的午後風景。傳承四代的堅持，讓這攤與相隔不遠的矮仔成，成為海安路蝦仁飯的兩大門派，各有死忠支持者互不相讓，也讓這條老街多了一種良性競爭的美味風景。",
    "招牌蝦仁飯用柴魚湯與蝦頭熬煮的湯汁拌炒白飯，米粒濕潤帶點湯飯口感卻不失粒粒分明，火燒蝦鮮甜彈牙，加點一顆半熟鴨蛋剖開淋上蛋液拌勻，滋味瞬間升級，鹹香濃郁又帶點蛋香回甘，是行家才懂的加分吃法，湯汁滲入米粒的濕潤感令人一口接一口，柴魚香氣也在每一口裡緩緩擴散開來。",
    "半熟鴨蛋蛋黃綿密，剖開淋在蝦仁飯上拌勻，是加點率最高的靈魂配角；魚丸湯魚丸Q彈有嚼勁，湯頭清爽不油膩，是搭配蝦仁飯解膩的最佳選擇，兩者搭配讓一碗蝦仁飯有了更豐富的層次變化，也讓整頓午餐更顯完整，價格同樣親民不貴，是海安路小吃巡禮裡最超值的組合，值得每一樣都點來嘗嘗。",
    "集品的蝦仁飯口感偏濕潤香甜，適合喜歡湯飯口感、重視蝦鮮風味的饕客，搭配半熟鴨蛋更是必點組合。與相距約兩百公尺的矮仔成相比，集品的米飯更濕潤入味，湯飯的香氣也更加濃厚，是海安路小吃巡禮不能錯過的一站，值得兩家一起比較品嘗，感受不同門派對同一道小吃的堅持與詮釋，也是外地朋友來訪時的必推選項，百去不厭，屢試不爽，總能滿足胃口與鄉愁。"
   ],
