   "tagline": "米其林連年點名，國華街小卷米粉的另一派宗師",
   "story": "葉家小卷米粉創立於1935年，至今已傳承三代、超過八十年歷史，與鄰近的邱家小卷米粉各有擁戴者，是國華街上另一條排隊人龍的來源。店家維持傳統做法，大鍋熬湯、現燙小卷，連續多年獲得米其林必比登推薦，觀光客與饕客絡繹不絕。米粉選用中粗米粉，口感介於一般米粉與米苔目之間，滑溜好入口，是葉家獨有的識別度。即使賣完提早收攤也甘願排隊的人潮，足見這碗湯頭在台南人心中的地位。",
   "review": [
    "國華街二段的葉家招牌不算顯眼，隊伍卻總是排到街邊，店家維持古早的大鍋熬湯方式，蒸氣裊裊，光是聞著香氣就讓人食指大動。創立於1935年，傳承三代超過八十年，連續多年獲得米其林必比登推薦，與鄰近的邱家小卷米粉各有擁戴者，是國華街上另一條排隊人龍的來源。店家維持傳統做法，大鍋熬湯、現燙小卷，即使賣完提早收攤也甘願排隊的人潮，足見這碗湯頭在台南人心中的地位。",
    "小卷米粉端上桌，新鮮大塊的小卷咬下去嫩中帶Q，相當過癮，米粉滑溜近似米苔目口感，是葉家的一大特色，選用中粗米粉，口感介於一般米粉與米苔目之間；湯頭略帶甘甜，喜歡清爽口味的人可依個人喜好加桌上胡椒粉提香，增添一層辛香尾韻。",
    "綜合米粉湯依當日供應搭配多樣海鮮配料，湯頭與招牌款相同，適合想一次品嚐多種食材的顧客；黑白切小菜可搭配米粉湯一起享用，補足蛋白質與口感層次，是熟客會多加點的簡單配菜，讓一碗湯麵吃起來更加豐盛完整，配菜的選項也讓不同喜好的人都能找到合意的搭配。",
    "連續多年拿下米其林必比登，讓這碗湯品成為國內外饕客朝聖的目標，適合喜歡Q彈口感米粉、想比較葉邱兩家小卷米粉差異的旅人。比起邱家湯頭的鹹鮮濃郁，葉家略帶甘甜，提早收攤的特性也提醒大家想吃就得早點出發，即使賣完提早收攤也甘願排隊的人潮，足見這碗湯頭在台南人心中的地位，也讓國華街多了一個必訪的排隊風景。"
   ],
