     "desc": "選用新鮮虱目魚肚熬煮，魚肚保留油脂與細嫩肉質，粥底米粒偏綿密帶湯感，不同於飯湯的粒粒分明，油蔥香氣濃郁，入口鮮甜溫潤、魚腥味處理得極乾淨，是店內詢問度最高、也最能代表阿堂功力的招牌品項，值回票價，值得一早特地起床前來品嘗。",
