     "desc": "選用虱目魚腱肉簡單拌炒，保留魚肉最原始的彈牙口感與鮮甜滋味，不多加調味便能吃出魚肉本身的細緻與新鮮度，蒜末爆香提味卻不搶戲，展現自家養殖食材的高品質與老闆對火候的精準掌握，是老饕評價相當高的一道家常菜。",
