     "desc": "虱目魚柳裹粉油炸至外酥內嫩，搭配泰式酸辣醬汁與蒜末辣椒提味，酸甜辣交織的滋味開胃解膩，魚肉去刺處理細心，是餐桌上老少咸宜、接受度最高的一道料理，也常是小朋友最捧場的菜色之一，外層裹粉炸得金黃酥脆，沾點醬汁後酸甜滋味更加分明。",
