     "desc": "以日本昆布慢火熬煮湯底，湯色清澈卻鮮甜有層次，不添加味精或加工調味，配料有蛤蜊、豬肉片、白蝦、雞蛋與時蔬，食材新鮮原汁原味，麵條吸附湯汁後口感Q彈，是誠實鍋燒的招牌基本款，也是最能吃出昆布高湯用心的一碗。",
     "signature": true
