     "desc": "在招牌鍋燒基礎上大幅增加蛤蜊份量，鮮甜湯汁隨蛤蜊開殼釋放得更加濃郁，海味十足卻依然清爽不膩，昆布高湯的甘醇與蛤蜊鮮味層層疊加，是喜歡海鮮風味更濃厚顧客的首選升級版本，也是不少熟客回訪必點的固定選項，蛤蜊份量加倍卻不加價太多，深受海味控喜愛。",
