     "desc": "選用帶皮豬五花先煙燻後油煎，鹹香中帶著淡淡煙燻氣息，肥肉煎至微酥卻不乾柴，搭配店家自製酸菜，酸香開胃恰好化解油膩感，一口肉一口酸菜，越嚼越涮嘴，是不少熟客必點的下酒配飯菜色，肥肉入口即化卻不顯油膩，是店內下酒配飯皆宜的招牌小菜。",
