     "desc": "家傳六代的方子，用當歸、川芎、白芍、熟地、人參、茯苓、白朮、炙甘草、黃耆、肉桂十味藥材燉製，味道濃郁厚實又不失溫潤，是博仁堂最具代表性的招牌，也最能體現這間老中藥行轉型餐廳的底蘊與誠意，很多熟客專程為這一味而來。",
