     "name": "溫體牛肉湯",
     "price": "約NT$200",
     "dish_type": "牛肉湯",
     "desc": "選用當日現宰溫體牛肉，薄切後淋上滾燙牛骨高湯瞬間燙熟，肉片粉嫩帶著自然甜味，口感軟嫩不柴，湯頭清澈透亮不油膩，喝完全身暖和，是店內最具代表性、也是撐起這塊招牌超過三十年的靈魂餐點，凌晨排隊也要吃到的一碗。",
     "signature": true
