   "id": "baa-wanli-goat",
   "name": "咩灣裡羊肉店",
   "category": "羊肉湯",
   "district": "南區",
   "area": "興南街",
   "address": "台南市南區興南街36號",
   "lat": 22.9663,
   "lng": 120.1936,
   "hours": "11:00–20:00",
