     "desc": "芋頭燉得綿密沙軟，融進牛奶清冰中，口感濃郁滑順不死甜，冰體本身帶著淡淡奶香，與芋頭沙沙的口感相輔相成，芋頭控必點的品項，甜度拿捏得宜、吃到最後也不覺得膩口。",
