     "desc": "每日現煮現磨的豆花，不加防腐劑與人工香料，口感綿密滑順、入口即化，無明顯豆腥味，搭配黑糖水或糖水後甜度適中不搶味，是店內最經典、也最能展現豆花本質的品項。",
