     "desc": "鱔魚肉大火快炒逼出鑊香，勾芡後帶著焦糖化的甜鹹醬香，肉質保持脆嫩不軟爛，起鍋速度極快才能鎖住彈性，是府城酒家菜系裡最考驗火候的一道招牌熱炒。",
