     "desc": "牛肉先快火拉炒後上鐵板續煮，端上桌滋滋作響香氣四溢，肉片邊緣微焦、中心仍保有粉嫩色澤，鹹香醬汁滲入白飯裡，配上洋蔥絲增添甜味，是熟客下班後犒賞自己的固定班底，也是外帶便當裡最受歡迎、常常一開賣就被點光的一格。",
