     "desc": "同款扁魚沙茶湯底，換上油花分布均勻的豬肉片，涮煮後肉質軟嫩多汁，湯頭吸附肉香後更加濃郁厚實，配上白飯與時蔬一起食用份量十足，價格比牛肉爐更親民實惠，是學生與上班族最常點的選擇，也是荷包友善的深夜首選。",
