     "desc": "油麵燙熟後拌入燙好的豆芽菜，淋上特調醬油與油蔥酥攪拌均勻，麵條沾滿醬汁卻不顯油膩，豆芽菜清脆爽口中和鹹香，簡單卻扎實飽足，價格銅板到不可思議，是新營人早餐桌上必不可少的樸素滋味，也是外地人吃過就忘不了的家鄉味。",
