     "desc": "大火快炒逼出蔥段香氣，豬肉片邊緣微焦、內裡依然軟嫩多汁，鹹甜醬汁裹滿每一片肉，鋪在白飯上油亮誘人，鑊氣十足香氣四溢，蔥段脆度與甜味也拿捏得剛好，白飯吸附醬汁後格外下飯，是店內詢問度最高、幾乎人人必點的招牌便當首選之一。",
