    {
     "name": "蔥爆羊肉",
     "price": "約NT$180",
     "dish_type": "羊肉湯",
     "desc": "羊肉片大火快炒配上大量蔥段，鑊氣十足、鹹香夠味，肉質保留彈性不過老，蔥段的辛香提出羊肉的甘甜，是熱炒愛好者點來配飯配酒的招牌菜色，也展現老泰羊肉不只賣湯品、熱炒功夫同樣紮實的多元手路，起鍋前淋一點米酒提香，讓整道菜多了一股熱炒店特有的酒香尾韻。",
     "signature": false
    }
