     "desc": "以薄魚漿包裹內餡捲製而成，口感較魚丸更細緻軟嫩，帶點海味清甜，切片後紋理分明，適合清蒸或煮湯，是熟悉市場文化的老饕才會特別指名購買的隱藏品項，也是芬蘭魚丸攤上最考驗手工細緻度的一項產品，咬下時內餡的鮮甜隨著薄皮一起釋放，口感比一般魚丸更加輕盈細膩。",
