  "notes": "台南自《臺灣米其林指南2024》（2024/8/27公布）起首度納入評選，與台北、台中、高雄並列。2026年版已於2026/7/21公布（含台南、新竹首度摘星），故2024～2026三個年度均已查證齊全，非「尚未公布」。各年台南必比登家數：2024年31家（新增3家：添厚、麥謎食驗室、葉桑生炒鴨肉焿/羹）；2025年30家（新增1家：蓮霧腳羊肉湯；除名2家：黑琵食堂、永通虱目魚粥）；2026年30家（新增3家：咩灣裡羊肉店、詹記、竹記冬菜鴨；除名3家：麥謎食驗室、東香台菜海味料理、筑馨居）。三年合計不重複店家共35家。地址主要取自新聞報導與部落格整理（非官方逐店頁面，guide.michelin.com店家頁在自動化查詢環境下回傳403無法直接抓取，michelin_url暫留null，之後可人工於guide.michelin.com手動查對補上）；黃家蝦捲、阿興虱目魚地址在不同來源間略有出入（阿興虱目魚已依店家遷址更新為北區文賢路311號，舊資料為252號），田媽媽長盈海味屋每週僅營業六日兩天。星級與入選推薦(Selected)店家依指示未整理。",
